bun -e '
const fs = require("fs");
const readline = require("readline");

const file = "/data00/home/zhangpeng.pada/.claude/projects/-data00-home-zhangpeng-pada--herdr-worktrees-navi-driving-maneuver-worktree-green-cloud-3b4b/4ce3e3a2-7482-4acd-b2ff-6c86edf5a13b.jsonl";
const rl = readline.createInterface({
  input: fs.createReadStream(file),
  crlfDelay: Infinity
});

let lineNo = 0;
let lines = [];

rl.on("line", (line) => {
  lineNo++;
  try {
    const data = JSON.parse(line);
    lines.push({
      lineNo,
      type: data.type,
      uuid: data.uuid,
      parentUuid: data.parentUuid,
      isSidechain: data.isSidechain,
      isMeta: data.isMeta,
      promptSource: data.promptSource,
      hasMessage: !!data.message,
      msgRole: data.message?.role,
      msgContentSummary: Array.isArray(data.message?.content) 
        ? data.message.content.map(c => c.type + (c.name ? ":" + c.name : "") + (c.text ? `(${c.text.slice(0, 30)}...)` : "")).join(", ")
        : (typeof data.message?.content === "string" ? data.message.content.slice(0, 50) : "")
    });
  } catch (e) {
    lines.push({ lineNo, error: e.message });
  }
});

rl.on("close", () => {
  console.log("Total lines:", lines.length);
  console.log(JSON.stringify(lines.slice(0, 40), null, 2));
});
'

